# Source-grounded SVG drawing primitives. Fixed viewBox provides a pan/zoom canvas on small screens.
def txt(x,y,text,cls='label',anchor='middle'):
 parts=text.split('|');return ''.join(f'<text x="{x}" y="{y+i*20}" text-anchor="{anchor}" class="{cls}">{E(p)}</text>'for i,p in enumerate(parts))
def node(id,x,y,label,sub='',kind='box',w=156,h=66,info=''):
 if kind=='circle':shape=f'<circle cx="{x}" cy="{y}" r="36"/>';text=txt(x,y-4,label)+txt(x,y+18,sub,'sub')
 elif kind=='gate':shape=f'<rect x="{x-w/2}" y="{y-h/2}" width="{w}" height="{h}" rx="5"/><path class="gate-bar" d="M{x-45} {y-h/2+9}V{y+h/2-9}M{x+45} {y-h/2+9}V{y+h/2-9}"/>';text=txt(x,y-5,label)+txt(x,y+17,sub,'sub')
 elif kind=='file':shape=f'<path d="M{x-w/2} {y-h/2}H{x+w/2-14}L{x+w/2} {y-h/2+14}V{y+h/2}H{x-w/2}Z"/>';text=txt(x,y-5,label)+txt(x,y+17,sub,'sub')
 else:shape=f'<rect x="{x-w/2}" y="{y-h/2}" width="{w}" height="{h}" rx="{h/2 if kind=="pill" else 10}"/>';text=txt(x,y-5,label)+txt(x,y+17,sub,'sub')
 return f'<g id="n-{id}" class="node {kind}" data-node="{id}" role="button" tabindex="0" aria-label="{E(label+": "+(info or sub))}" data-info="{E(info or sub)}">{shape}{text}<path class="blocked-mark" d="M{x-16} {y-14}L{x+16} {y+14}M{x+16} {y-14}L{x-16} {y+14}"/></g>'
def edge(id,x1,y1,x2,y2,label='',kind='',bend=0):
 d=f'M{x1} {y1}L{x2} {y2}'if not bend else f'M{x1} {y1}Q{(x1+x2)/2} {(y1+y2)/2+bend} {x2} {y2}'
 return f'<g class="edge-wrap {kind}" data-edge="{id}"><path id="e-{id}" class="edge" d="{d}" marker-end="url(#arrow-head)"/>'+ (txt((x1+x2)/2,(y1+y2)/2+bend/2-10,label,'edge-label')if label else '')+'</g>'
def svg(content,title):return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 450" role="img" aria-label="'+E(title)+'"><defs><marker id="arrow-head" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z"/></marker></defs>'+content+'<g id="travel-token" aria-hidden="true"><circle r="10"/><circle r="4" class="token-center"/></g></svg>'
def make(nodes,edges,title,extras=''):
 return svg(extras+''.join(edge(*x)for x in edges)+''.join(node(*x)for x in nodes),title)
def step(caption,edgeid='',nodes=(),state='',blocked=()):return dict(caption=caption,edge=edgeid,nodes=list(nodes),state=state,blocked=list(blocked))
scenes=[]
def scene(id,title,summary,takeaway,diagram,steps,refs,detail,variants=None,mermaid=None):
 scenes.append(dict(id=id,title=title,summary=summary,takeaway=takeaway,svg=diagram,steps=steps,refs=refs.split(),detail=detail,variants=variants or {},mermaid=mermaid))
